package app.unifeed.media; import java.io.IOException; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; @RestController @RequestMapping("/api/v1/media") public class MediaController {private final MediaStorageService s;public MediaController(MediaStorageService s){this.s=s;}@PostMapping MediaStorageService.MediaPaths upload(@RequestParam MultipartFile file,@RequestParam MediaStorageService.Category category)throws IOException{return s.store(file,category);}}
